---@class RedDotConfig
local RedDotConfig = T(Global, "RedDotConfig")

---@public 红点结构树(子游戏自由替换)
RedDotConfig.profile = {

}

local prefix = 'rd'
local allocatedKeys = {}
---@public 自动分配一个不会重复的key
function RedDotConfig:allocateKey(level)
    if type(level) ~= "number" or level < 1 then ---这里顺序不可以调换
        return ''
    end
    local key = prefix
    for i = 1, level do
        if not allocatedKeys[i] then
            allocatedKeys[i] = 0
        end
        local idx = (i == level) and allocatedKeys[i] + 1 or allocatedKeys[i]
        if i == level then
            allocatedKeys[i] = allocatedKeys[i] + 1
        end
        key = key..'_'..idx
    end
    return key
end

return RedDotConfig